class Contagem:
    def __init__(self, inicio, fim):
        self.atual = inicio
        self.fim = fim
        if inicio <= fim:
            self.passo = 1
        else:
            self.passo = -1

    def __iter__(self):
        return self

    def __next__(self):
        if self.atual == self.fim + self.passo:
            raise StopIteration
        valor = self.atual
        self.atual += self.passo
        return valor


