import itertools


def soma_dos_quadrados(n):
    return sum(x * x for x in range(1, n + 1))


def impares():
    n = 1
    while True:
        yield n
        n += 2


def primeiros(gerador, k):
    return list(itertools.islice(gerador, k))


print(soma_dos_quadrados(3))
print(primeiros(impares(), 5))

