from contextlib import contextmanager


class Missao:
    def __init__(self, nome):
        self.nome = nome

    def __enter__(self):
        print(f"[início] {self.nome}")
        return self

    def __exit__(self, tipo, valor, rastro):
        engolir = isinstance(valor, ValueError)
        if engolir:
            print(f"[erro] {self.nome}: {valor}")
        print(f"[fim] {self.nome}")
        return engolir


@contextmanager
def moldura(largura):
    print("=" * largura)
    try:
        yield
    finally:
        print("=" * largura)


# Não mude daqui para baixo
with Missao("Dragão"):
    print("lutando...")
    raise ValueError("espada quebrou")

with moldura(10):
    print("Fim de jogo")

