from dataclasses import dataclass, field


@dataclass(order=True)
class Item:
    preco: int
    nome: str
    peso: float = 1.0


@dataclass
class Mochila:
    dono: str
    capacidade: float = 10.0
    itens: list = field(default_factory=list)

    def peso_total(self) -> float:
        return sum(item.peso for item in self.itens)

    def adicionar(self, item: Item) -> bool:
        if self.peso_total() + item.peso <= self.capacidade:
            self.itens.append(item)
            return True
        return False


