import functools

PEDIDOS = '''# pedidos de sábado
Ana;maçã;3;4
Léo;pera;0;5

Bia;uva;2;10
isto não é um pedido
   Caio;maçã;5;4
Duda;kiwi;dois;3
'''


def ignorar_erros(func):
    @functools.wraps(func)
    def embrulho(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except ValueError:
            return None
    return embrulho


@ignorar_erros
def para_pedido(linha):
    cliente, produto, quantidade, preco = linha.split(";")
    return (cliente, produto, int(quantidade), int(preco))


def ler_linhas(texto):
    for linha in texto.split("\n"):
        linha = linha.strip()
        if linha and not linha.startswith("#"):
            yield linha


def separar(linhas):
    for linha in linhas:
        pedido = para_pedido(linha)
        if pedido is not None:
            yield pedido


def com_quantidade(pedidos):
    for pedido in pedidos:
        if pedido[2] > 0:
            yield pedido


def com_total(pedidos):
    for cliente, produto, quantidade, preco in pedidos:
        yield (cliente, produto, quantidade * preco)


def fechar_caixa(texto):
    soma = 0
    quantos = 0
    for cliente, produto, total in com_total(com_quantidade(separar(ler_linhas(texto)))):
        print(f"{cliente}: {produto} = {total} moedas")
        soma += total
        quantos += 1
    print(f"Total: {soma} moedas em {quantos} pedidos")


if __name__ == "__main__":
    fechar_caixa(PEDIDOS)
